{
  "candidates": [
    {
      "subpart": "PPPP",
      "title": "National Emission Standards for Hazardous Air Pollutants: Plastic Parts and Products Surface Coating",
      "gates": [
        {
          "type": "source_category",
          "question": "Does the operation involve surface coating (the application of coating to a substrate) of plastic parts or products?",
          "test": "yes: operation falls within the PPPP source category (surface coating of plastic parts and products); no: PPPP source-category gate not met",
          "citations": [
            "40 CFR 63.4481(a)"
          ],
          "quote": "Surface coating is the application of coating to a substrate using, for example, spray guns or dip tanks. When application of coating to a substrate occurs, then surface coating also includes associated activities, such as surface preparation, cleaning, mixing, and storage."
        },
        {
          "type": "affected_source",
          "question": "Is the solvent welding step part of a 'coating operation' (i.e., the point at which a given quantity of coating or cleaning material is applied and subsequent points where organic HAP are emitted)?",
          "test": "yes: the solvent welding step is part of the affected source and covered as a coating operation; no: the step may not be within the affected source definition for PPPP",
          "citations": [
            "40 CFR 63.4581"
          ],
          "quote": "but always includes at least the point at which a given quantity of coating or cleaning material is applied to a given part and all subsequent points in the affected source where organic HAP are emitted"
        },
        {
          "type": "major_or_area",
          "question": "Is the facility a major source of HAP (any single HAP ≥ 9.07 Mg (10 tons)/yr or any combination of HAP ≥ 22.68 Mg (25 tons)/yr)?",
          "test": "yes: facility meets the major-source criterion referenced in PPPP; no: facility is area/source-level and PPPP applicability may differ",
          "citations": [
            "40 CFR 63.4481(b)"
          ],
          "quote": "A major source of HAP emissions is any stationary source or group of stationary sources located within a contiguous area and under common control that emits or has the potential to emit any single HAP at a rate of 9.07 megagrams (Mg) (10 tons) or more per year or any combination of HAP at a rate of 22.68 Mg (25 tons) or more per year."
        },
        {
          "type": "threshold",
          "question": "Does the affected source use 378 liters (100 gallons) per year or more of coatings that contain hazardous air pollutants in the surface coating of plastic parts and products?",
          "test": "yes: the 100-gallon-per-year material-use threshold is met and PPPP may apply; no: below the threshold and PPPP may not apply based on that criterion",
          "citations": [
            "40 CFR 63.4481(b)"
          ],
          "quote": "that uses 378 liters (100 gallons (gal)) per year, or more, of coatings that contain hazardous air pollutants (HAP) in the surface coating of plastic parts and products;"
        },
        {
          "type": "exemption",
          "question": "Does the operation meet any exclusion in § 63.4481(c) (e.g., the facility uses only coatings, thinners, additives, and cleaning materials that contain no organic HAP)?",
          "test": "yes: operation meets an exclusion in § 63.4481(c) and that coating operation is not subject to PPPP; no: no exclusions apply",
          "citations": [
            "40 CFR 63.4481(c)(1)"
          ],
          "quote": "A coating operation conducted at a facility where the facility uses only coatings, thinners and other additives, and cleaning materials that contain no organic HAP, as determined according to § 63.3941(a)."
        },
        {
          "type": "compliance_date",
          "question": "Is the affected source new or reconstructed (i.e., subject to the new/reconstructed affected-source provisions)?",
          "test": "yes: new/reconstructed source subject to 'new source' emission limits and requirements; no: existing-source requirements apply",
          "citations": [
            "40 CFR 63.4490(a)"
          ],
          "quote": "For a new or reconstructed affected source, you must limit organic HAP emissions to the atmosphere from the affected source to the applicable limit specified in paragraphs (a)(1) through (4) of this section, except as specified in paragraph (c) of this section, determined according to the requirements in § 63.4541, § 63.4551, or § 63.4561."
        }
      ],
      "missing": [
        "Whether the methylene chloride application is being used 'for the purpose of bonding' (i.e., as an adhesive/coating) versus being used solely as a cleaning/solvent step",
        "Annual quantity (volume) of methylene chloride and other coatings/solvents used in the solvent-welding lines to determine the 100-gallon-per-year threshold",
        "Whether any coating solids or dry film remain on the parts after the operation (user stated 'no dry film' but confirm with measurements or definition application)",
        "Whether the solvent welding step is performed at equipment listed in the affected-source definition (coating operations, storage/mixing, conveyance, waste handling) tied to the PPPP affected source",
        "Whether the facility is new/reconstructed for these added lines or existing (affects which emission limits apply) despite the facility being a major source"
      ]
    },
    {
      "subpart": "A",
      "title": "General Provisions (Applicability of §§ 63.1 through 63.15)",
      "gates": [
        {
          "type": "source_category",
          "question": "Do the General Provisions in §§ 63.1 through 63.15 (Subpart A) apply to this affected source?",
          "test": "yes: the General Provisions identified in Table 2 to PPPP apply and must be followed; no: consult Table 2 for specific exclusions",
          "citations": [
            "40 CFR 63.4501"
          ],
          "quote": "Table 2 to this subpart shows which parts of the General Provisions in §§ 63.1 through 63.15 apply to you."
        }
      ],
      "missing": [
        "Table 2 to subpart PPPP showing which specific sections of the General Provisions (§§ 63.1-63.15) apply to the affected source (not provided in the supplied sections)"
      ]
    },
    {
      "subpart": "IIII",
      "title": "Surface Coating of Automobiles and Light-Duty Trucks (referenced as an alternative NESHAP)",
      "gates": [
        {
          "type": "source_category",
          "question": "Does the facility meet the applicability criteria of Subpart IIII (Surface Coating of Automobiles and Light-Duty Trucks) so that you may elect to comply with subpart IIII instead of PPPP for some coating operations?",
          "test": "yes: you may elect compliance under subpart IIII for applicable plastic-part coatings intended for vehicles; no: subpart IIII is not an available alternative",
          "citations": [
            "40 CFR 63.4481(d)"
          ],
          "quote": "you may choose to comply with the requirements of subpart IIII of this part in lieu of complying with this subpart."
        }
      ],
      "missing": [
        "Whether the plastic parts being coated are intended for use on automobiles or light-duty trucks such that §§ 63.3081/63.3082 applicability criteria would be met (text of §§ 63.3081/63.3082 not provided)",
        "Details necessary to determine whether the vehicle-related criteria in subpart IIII apply to these specific parts or coating operations"
      ]
    }
  ],
  "checklist": [
    {
      "item": "Is the methylene chloride application performed for the purpose of bonding two plastic surfaces (i.e., applied as an adhesive/coating per the PPPP definition)?",
      "gate": "affected_source"
    },
    {
      "item": "Does the solvent application leave any coating solids or a dry film on the substrate after processing?",
      "gate": "affected_source"
    },
    {
      "item": "Does the applied material qualify as a 'coating' or 'adhesive' under 40 CFR 63.4581 (manufacturer's function and definitions)?",
      "gate": "affected_source"
    },
    {
      "item": "What is the annual amount (liters or gallons per year) of coatings/solvents containing HAP used in the solvent-welding lines (is it ≥ 378 L / 100 gal per year)?",
      "gate": "threshold"
    },
    {
      "item": "Is the facility a major source of HAP (any single HAP ≥ 9.07 Mg (10 tons)/yr or combined HAP ≥ 22.68 Mg (25 tons)/yr)?",
      "gate": "major_or_area"
    }
  ]
}

{
  "candidates": [
    {
      "subpart": "M",
      "title": "National Perchloroethylene Air Emission Standards for Dry Cleaning Facilities",
      "gates": [
        {
          "type": "source_category",
          "question": "Does this facility use perchloroethylene (PCE)?",
          "test": "yes -> Subpart M applies to the facility; no -> Subpart M does not apply",
          "citations": [
            "40 CFR 63.320(a)",
            "40 CFR 63.320(b)"
          ],
          "quote": "(a) The provisions of this subpart apply to the owner or operator of each dry cleaning facility that uses perchloroethylene. (b) The compliance date for a new dry cleaning system depends on the date that construction or reconstruction commences."
        },
        {
          "type": "affected_source",
          "question": "Is the dry cleaning system located in a building that contains a residence (for example, an apartment above the shop)?",
          "test": "yes -> Additional requirements/controls for machines in buildings with residences may apply; no -> those residence-specific requirements do not apply",
          "citations": [
            "40 CFR 63.322(o)(5)(i)"
          ],
          "quote": "After December 21, 2020, the owner or operator shall eliminate any emission of PCE from any dry cleaning system that is located in a building with a residence."
        },
        {
          "type": "major_or_area",
          "question": "Is the dry cleaning facility a major source (emits or has potential to emit >9.1 megagrams (10 tons) PCE per year)?",
          "test": "yes -> Major-source provisions apply; no -> facility is an area source and area-source provisions apply",
          "citations": [
            "40 CFR 63.320(g)"
          ],
          "quote": "A dry cleaning facility is a major source if the facility emits or has the potential to emit more than 9.1 megagrams per year (10 tons per year) of perchloroethylene to the atmosphere."
        },
        {
          "type": "threshold",
          "question": "Is the facility's total yearly PCE consumption less than 530 liters (140 gallons) per year (relevant to certain exemptions for some existing machines)?",
          "test": "yes -> Certain provisions of §§63.322, 63.323, and 63.324 may be exempted per §63.320(d); no -> those exemptions do not apply",
          "citations": [
            "40 CFR 63.320(d)"
          ],
          "quote": "if the total PCE consumption of the dry cleaning facility is less than 530 liters (140 gallons) per year. Consumption is determined according to § 63.323(d)."
        },
        {
          "type": "compliance_date",
          "question": "Was the dry cleaning system present (installed/operating) on or after December 21, 2020 (i.e., is the compliance date in effect for the residence-location requirement)?",
          "test": "yes -> The December 21, 2020 residence-location requirement (§63.322(o)(5)(i)) is operative; no -> the residence-location requirement still applies after that date, but historical compliance timing considerations may differ",
          "citations": [
            "40 CFR 63.322(o)(5)(i)"
          ],
          "quote": "After December 21, 2020, the owner or operator shall eliminate any emission of PCE from any dry cleaning system that is located in a building with a residence."
        }
      ],
      "missing": [
        "Total yearly PCE consumption at the facility (liters or gallons per 12-month period)",
        "Type of dry cleaning machine(s) present (dry-to-dry or transfer machine system)",
        "Date construction, installation, or reconstruction commenced for the dry cleaning system (to determine 'new' vs 'existing')",
        "Whether the machine is coin-operated",
        "Whether the facility is a major source (can be derived from consumption/emissions if not directly known)",
        "Whether any equivalents or alternative control demonstrations have been approved for this source"
      ]
    },
    {
      "subpart": "A",
      "title": "General Provisions",
      "gates": [
        {
          "type": "source_category",
          "question": "Is this an affected source for which a relevant standard has been established under section 112 of the Act?",
          "test": "yes -> General Provisions in §63.6 apply to compliance dates, operation, and maintenance; no -> §63.6 does not apply",
          "citations": [
            "40 CFR 63.6(a)(1)"
          ],
          "quote": "The requirements in this section apply to the owner or operator of affected sources for which any relevant standard has been established pursuant to section 112 of the Act"
        }
      ],
      "missing": [
        "Confirmation that a relevant standard under section 112 applies to this specific source (Subpart M is a relevant standard if PCE is used)",
        "Whether any extension of compliance under §63.6(i) has been requested or granted"
      ]
    },
    {
      "subpart": "EEEE",
      "title": "General requirements for Subpart EEEE (included General Provisions cross-references)",
      "gates": [
        {
          "type": "source_category",
          "question": "Does Subpart EEEE's equipment list (§63.2338(b)(1)-(5)) include equipment at this facility and is that equipment in OLD operation?",
          "test": "yes -> Subpart EEEE's operating and maintenance requirements (and cross-references to §63.6) apply; no -> Subpart EEEE is not applicable",
          "citations": [
            "40 CFR 63.2350(b)"
          ],
          "quote": "Except as specified in paragraph (d) of this section, you must always operate and maintain your affected source, including air pollution control and monitoring equipment, according to the provisions in § 63.6(e)(1)(i)."
        }
      ],
      "missing": [
        "Whether the shop's equipment is listed in §63.2338(b)(1)-(5) (i.e., whether Subpart EEEE enumerated equipment is present)",
        "Whether the equipment is in 'OLD' operation as defined by Subpart EEEE",
        "Relevant compliance dates for Subpart EEEE for the specific equipment"
      ]
    }
  ],
  "checklist": [
    {
      "item": "Do you use perchloroethylene (PCE) at this facility?",
      "gate": "source_category"
    },
    {
      "item": "Is the dry cleaning machine located in a building that contains a residence (e.g., apartment above the shop), even if currently vacant?",
      "gate": "affected_source"
    },
    {
      "item": "What is the facility's total yearly PCE consumption (sum of past 12 months in liters or gallons)?",
      "gate": "threshold"
    },
    {
      "item": "Is the facility a major source (>9.1 Mg / 10 tons PCE per year)?",
      "gate": "major_or_area"
    },
    {
      "item": "When was the dry cleaning system constructed, installed, or reconstructed (date) or was it present on/after December 21, 2020?",
      "gate": "compliance_date"
    }
  ]
}

{
  "candidates": [
    {
      "subpart": "LLL",
      "title": "Portland Cement Plants (Subpart LLL)",
      "gates": [
        {
          "type": "source_category",
          "question": "Is the facility a portland cement plant (new or existing) that is an area or major source?",
          "test": "yes: proceed to evaluate Subpart LLL gates; no: Subpart LLL does not apply",
          "citations": [
            "40 CFR 63.1340(a)"
          ],
          "quote": "The provisions of this subpart apply to each new and existing portland cement plant which is a major source or an area source as defined in § 63.2."
        },
        {
          "type": "affected_source",
          "question": "Does the coal mill qualify as an inline coal mill (i.e., uses kiln exhaust gases) or is it otherwise listed as an affected source in this subpart?",
          "test": "yes: the coal mill is an affected source under Subpart LLL; no: the coal mill may not be an affected source under Subpart LLL",
          "citations": [
            "40 CFR 63.1340(b)(1)"
          ],
          "quote": "Each kiln including alkali bypasses and inline coal mills, except for kilns that burn hazardous waste and are subject to and regulated under subpart EEE of this part;"
        },
        {
          "type": "affected_source",
          "question": "Does the coal mill exhaust through its own separate stack (not commingled with the kiln main stack)?",
          "test": "yes: treat coal mill stack as a separate emission point for testing and combined-emission calculations; no: treat exhaust as commingled with kiln and follow commingled procedures",
          "citations": [
            "40 CFR 63.1349(b)(1)(viii)"
          ],
          "quote": "When there is an alkali bypass and/or an inline coal mill with a separate stack associated with a kiln, the main exhaust and alkali bypass and/or inline coal mill must be tested simultaneously and the combined emission rate of PM"
        },
        {
          "type": "major_or_area",
          "question": "Is the portland cement plant a major source (vs an area source) as defined in §63.2?",
          "test": "yes: major-source limits and monitoring requirements apply where specified; no: area-source limits and monitoring requirements apply",
          "citations": [
            "40 CFR 63.1340(a)"
          ],
          "quote": "The provisions of this subpart apply to each new and existing portland cement plant which is a major source or an area source as defined in § 63.2."
        },
        {
          "type": "threshold",
          "question": "Is the coal mill exhaust commingled with the kiln exhaust or otherwise combined with clinker cooler/alkali bypass exhaust to the PM control device?",
          "test": "yes: apply combined PM emissions calculation or alternative PM limit per commingling provisions; no: apply PM limits and testing to the separate coal mill stack (and account for combined emissions per separate-stack rules)",
          "citations": [
            "40 CFR 63.1343(b)(2)"
          ],
          "quote": "When there is an alkali bypass and/or an inline coal mill with a separate stack associated with a kiln, the combined PM emissions from the kiln and the alkali bypass stack and/or the inline coal mill stack are subject to the PM emissions limit."
        }
      ],
      "missing": [
        "Whether the coal mill uses kiln exhaust gases (i.e., meets the definition of an inline coal mill)",
        "Whether the coal mill exhaust is routed to its own separate stack or is commingled with kiln/clinker cooler exhaust",
        "Whether the coal mill exhaust is routed to the kiln's PM control device (i.e., combined stream) or to a separate PM control device",
        "Whether the plant is a major source or an area source (per §63.2)",
        "Type and configuration of PM control device(s) on the coal mill and kiln (baghouse, ESP, uncontrolled, etc.)",
        "Stack flow rates and whether continuous flow monitoring is installed or will use maximum design flow for testing"
      ]
    },
    {
      "subpart": "A",
      "title": "General Provisions (Subpart A)",
      "gates": [
        {
          "type": "source_category",
          "question": "Do the general definitions and applicable procedural provisions in Subpart A of part 63 apply to this source or its compliance actions?",
          "test": "yes: use Subpart A definitions/procedures where this subpart references them; no: do not rely on Subpart A for undefined terms/procedures",
          "citations": [
            "40 CFR 63.1341"
          ],
          "quote": "All terms used in this subpart that are not defined in this section have the meaning given to them in the CAA and in subpart A of this part."
        }
      ],
      "missing": []
    },
    {
      "subpart": "OOO",
      "title": "Nonmetallic Mineral Processing Plants (Part 60 Subpart OOO)",
      "gates": [
        {
          "type": "source_category",
          "question": "Is the coal mill (or the onsite source) subject to standards for nonmetallic mineral processing plants under 40 CFR part 60 subpart OOO?",
          "test": "yes: that onsite source is excluded from Subpart LLL per §63.1340(c); no: Subpart LLL may apply to the coal mill",
          "citations": [
            "40 CFR 63.1340(c)"
          ],
          "quote": "Onsite sources that are subject to standards for nonmetallic mineral processing plants in subpart OOO, part 60 of this chapter are not subject to this subpart."
        }
      ],
      "missing": [
        "Whether the coal mill or coal preparation activity at the site is subject to 40 CFR part 60 subpart OOO (or other NSPS for coal preparation) rather than Subpart LLL"
      ]
    }
  ],
  "checklist": [
    {
      "item": "Confirm the facility is a portland cement plant (new or existing) and determine major vs area source status.",
      "gate": "source_category"
    },
    {
      "item": "Confirm whether the coal mill uses kiln exhaust gases (i.e., is an inline coal mill as defined in §63.1341).",
      "gate": "affected_source"
    },
    {
      "item": "Confirm whether the coal mill exhaust is discharged through its own separate stack or is commingled with kiln/clinker cooler exhaust.",
      "gate": "affected_source"
    },
    {
      "item": "Confirm whether the coal mill exhaust is routed to the kiln PM control device (combined stream) or to a separate PM control device/stack.",
      "gate": "threshold"
    },
    {
      "item": "Determine whether the coal mill or onsite coal processing is subject to 40 CFR part 60 subpart OOO (or other NSPS), which would exclude it from Subpart LLL.",
      "gate": "source_category"
    }
  ]
}

{
  "candidates": [
    {
      "subpart": "YYYY",
      "title": "Stationary Combustion Turbines NESHAP (Subpart YYYY)",
      "gates": [
        {
          "type": "source_category",
          "question": "Is your unit a lean premix gas-fired stationary combustion turbine as defined by this subpart?",
          "test": "yes -> unit falls within the subpart category for lean premix gas-fired turbines; no -> this subpart's lean-premix gas-fired requirements likely do not apply",
          "citations": [
            "40 CFR 63.6100"
          ],
          "quote": "For each new or reconstructed stationary combustion turbine which is a lean premix gas-fired stationary combustion turbine, you must comply with the emission limitations and operating limitations in Table 1 and Table 2 of this subpart."
        },
        {
          "type": "affected_source",
          "question": "Is the stationary combustion turbine not equipped with an oxidation catalyst?",
          "test": "yes -> you must petition the Administrator for monitoring-based operating limitations or petition for no additional operating limitations before initial performance test; no -> catalyst inlet temperature monitoring requirements may apply",
          "citations": [
            "40 CFR 63.6120(e)"
          ],
          "quote": "If your stationary combustion turbine is not equipped with an oxidation catalyst, you must petition the Administrator for operating limitations that you will monitor to demonstrate compliance with the formaldehyde emission limitation in Table 1."
        },
        {
          "type": "affected_source",
          "question": "If you will petition the Administrator for approval of additional operating limitations, will your petition include the information required in paragraphs (f)(1) through (5)?",
          "test": "yes -> petition contains the listed identification, relationship, limit-setting, measurement and recalibration information; no -> petition will be incomplete under the subpart's requirements",
          "citations": [
            "40 CFR 63.6120(f)"
          ],
          "quote": "If you petition the Administrator for approval of additional operating limitations to demonstrate compliance with the formaldehyde emission limitation in Table 1, your petition must include the following information described in paragraphs (f)(1) through (5) of this section."
        },
        {
          "type": "affected_source",
          "question": "If you choose to petition for no additional operating limitations, will your petition include the information required in paragraphs (g)(1) through (7)?",
          "test": "yes -> petition addresses parameters, relationships, impossibility of limits, measurement and recalibration, and infeasibility rationale; no -> petition will be incomplete under the subpart's requirements",
          "citations": [
            "40 CFR 63.6120(g)"
          ],
          "quote": "If you petition the Administrator for approval of no additional operating limitations, your petition must include the information described in paragraphs (g)(1) through (7) of this section."
        },
        {
          "type": "affected_source",
          "question": "If you are not using an oxidation catalyst, will you continuously monitor the parameters specified in your approved petition?",
          "test": "yes -> you would meet the monitoring requirement described for non-catalyst turbines; no -> you would not meet the continuous-monitoring requirement",
          "citations": [
            "40 CFR 63.6125(b)"
          ],
          "quote": "If you are operating a stationary combustion turbine that is required to comply with the formaldehyde emission limitation and you are not using an oxidation catalyst, you must continuously monitor any parameters specified in your approved petition to the Administrator,"
        },
        {
          "type": "major_or_area",
          "question": "Is the stationary combustion turbine located at a major source of HAP emissions?",
          "test": "yes -> the unit is an affected source under this subpart (if other category criteria met); no -> the subpart applies to affected sources at major sources, so this subpart may not apply",
          "citations": [
            "40 CFR 63.6090(a)"
          ],
          "quote": "An affected source is any existing, new, or reconstructed stationary combustion turbine located at a major source of HAP emissions."
        },
        {
          "type": "threshold",
          "question": "Does the turbine have a rated peak power output of less than 1.0 megawatt (MW) at ISO standard day conditions?",
          "test": "yes -> the turbine does not have to meet the requirements of this subpart and subpart A; no -> the turbine remains subject to the subpart (unless other exemptions apply)",
          "citations": [
            "40 CFR 63.6090(a)(3)"
          ],
          "quote": "A stationary combustion turbine with a rated peak power output of less than 1.0 megawatt (MW) at International Organization for Standardization (ISO) standard day conditions, which is located at a major source, does not have to meet the requirements of this subpart and of subpart A of this part."
        },
        {
          "type": "exemption",
          "question": "Is the new or reconstructed turbine an emergency stationary combustion turbine or located on the North Slope of Alaska (i.e., meeting the limited-requirements subcategory)?",
          "test": "yes -> the unit does not have to meet the subpart requirements except initial notification; no -> full subpart requirements remain applicable (subject to other exemptions)",
          "citations": [
            "40 CFR 63.6090(b)(1)"
          ],
          "quote": "The stationary combustion turbine is an emergency stationary combustion turbine; or (ii) The stationary combustion turbine is located on the North Slope of Alaska."
        },
        {
          "type": "compliance_date",
          "question": "Was your new or reconstructed lean premix gas-fired stationary combustion turbine started up after March 9, 2022?",
          "test": "yes -> you must comply with the emissions and operating limitations upon startup; no -> if started on or before March 9, 2022, you must comply no later than March 9, 2022",
          "citations": [
            "40 CFR 63.6095(a)(4)"
          ],
          "quote": "after March 9, 2022, you must comply with the emissions limitations and operating limitations in this subpart upon startup of your affected source."
        },
        {
          "type": "compliance_date",
          "question": "If an initial performance test is required, will you submit a Notification of Intent to conduct the initial performance test at least 60 calendar days before the test?",
          "test": "yes -> meets notification timing requirement for initial performance test; no -> you would be out of compliance with the notification timing requirement",
          "citations": [
            "40 CFR 63.6145(e)"
          ],
          "quote": "If you are required to conduct an initial performance test, you must submit a notification of intent to conduct an initial performance test at least 60 calendar days before the initial performance test is scheduled to begin as required in § 63.7(b)(1)."
        },
        {
          "type": "compliance_date",
          "question": "If you are required to submit a Notification of Compliance Status after demonstrating compliance with the formaldehyde emission limitation, will you submit it within 60 calendar days following completion of the performance test?",
          "test": "yes -> meets the Notification of Compliance Status timing requirement; no -> you would be out of compliance with the deadline for submitting performance test results",
          "citations": [
            "40 CFR 63.6145(f)"
          ],
          "quote": "For each performance test required to demonstrate compliance with the emission limitation for formaldehyde, you must submit the Notification of Compliance Status, including the performance test results, before the close of business on the 60th calendar day following the completion of the performance test."
        }
      ],
      "missing": [
        "Exact startup date for the turbine (to determine applicable compliance date)",
        "Rated peak power output (MW) at ISO standard day conditions",
        "Whether the turbine is or will be equipped with an oxidation catalyst (you stated it is not, but confirmation and documentation)",
        "Whether the turbine is an emergency unit or located on the North Slope of Alaska",
        "Whether the facility is a major source of HAPs (you stated major source; supporting permit or inventory documentation)",
        "Whether you will submit a petition and, if so, full details: parameters proposed (e.g., gas producer turbine speed, inlet air temperature), relationships to HAP emissions, limit-setting methodology, measurement instruments and accuracy, and recalibration frequency",
        "Status of any prior performance test (date, methods) and whether an initial performance test is required or has been conducted"
      ]
    },
    {
      "subpart": "A",
      "title": "General Provisions (Subpart A)",
      "gates": [
